The first part of the result follows from Proposition~\ref{prop:equi-env}. Now to see that the statement about the welfare gap is true, we note the following: (1) For $0 \le \theta_\true < \thresA{c}$, both the group $\A$ and group $\B$ applicant have zero welfare because they have zero probability of admission and incur zero cost of effort; (2) For $\thresA{c} \le \theta_\true < \thresB{c}$, the group $\B$ has zero welfare (since they have zero probability of admission) whereas the group $\A$ with the same $\theta_\true$ has postive probability of admission and non-negative welfare; (3) For $\thresB{c} \le \theta_\true \le 1$, the group $\A$ and group $\B$ applicant with same $\theta_\true$ both have the same probability of admission but the group $\A$ applicant exerts less effort. This is because a applicant with environment-scaled rank $\theta_\pre$ exerts effort
\begin{align}
	e = \begin{cases}
		g^{-1} \left( \frac{g(\tilde e_0) \cdot f_\mix(c)}{f_\mix(\theta_\pre)} \right)& \text{ if } \theta_\pre > c \\
		e_0 & \text{o.w.}
	\end{cases}
\end{align}

For the same $\theta_\true$, the group $\A$ applicant has higher $\theta_\pre$, since
\begin{align*}
	f^{-1}_\mix(f(\theta_\true)\cdot \psi_\A) > f^{-1}_\mix(f(\theta_\true)\cdot \psi_\B).
\end{align*}
Since $e$ is decreasing in $\theta_\pre$, the group $\A$ applicant exerts less effort than the group $\B$ applicant.

Since $c < (f_\mix)^{-1}(f(\theta_\true)\cdot \psi_\B)$, we have that $\theta_\true > \thresB{c}$. Thus we may compute $\swelf^\A(\theta_\true)$ and $\frac{\partial }{\partial c}\swelf^\B(\theta_\true)$  as follows:
\begin{align*}
	\swelf^\A(\theta_\true) &= \frac{\rho}{1-c} - \cost(g^{-1} ( \frac{g(\tilde e_0)f_\mix(c)}{f(\theta_\true)\cdot \psi_\A} )  ), \\
	\swelf^\B(\theta_\true) &= \frac{\rho}{1-c} - \cost(g^{-1} ( \frac{g(\tilde e_0)f_\mix(c)}{f(\theta_\true)\cdot \psi_\B} )  ),
\end{align*}
where as before $\tilde e_0 = \cost^{-1}(\frac{\rho}{1-c})$.
Then we have:
\begin{align*}
	\frac{\partial }{\partial c} \swelf^\A(\theta_\true) &= \frac{\rho}{(1-c)^2} \\
	&\quad -\cost'( g^{-1} ( \frac{g(\tilde e_0)f_\mix(c)}{f(\theta_\true)\cdot \psi_\A} ) )\cdot (g^{-1})' ( \frac{g(\tilde e_0)f_\mix(c)}{f(\theta_\true)\cdot \psi_\A} ) \cdot\frac{g(\tilde e_0)(f_\mix)'(c) + f_\mix(c)g'(\tilde e_0) \frac{\partial \tilde e_0}{\partial c}}{f(\theta_\true)\cdot \psi_\A}
\end{align*}
We claim that $\frac{\partial }{\partial c} \swelf^\A(\theta_\true) > \frac{\partial }{\partial c}\swelf^\B(\theta_\true) $. We have the following facts:
\begin{align}
	&\frac{1}{\psi_\A}<\frac{1}{\psi_\B} \label{eq:gamma-ineq}\\
	&\cost '(x) \le \cost '(\tilde{x}) ~\forall x < \tilde{x} \label{eq:cost-convex}\\
	&g^{-1}(x) < g^{-1}(\tilde x)~\forall x < \tilde{x} \label{eq:g-increasing}\\
	&(g^{-1})'(x) \le (g^{-1})'(\tilde x)~\forall x < \tilde{x} \label{eq:g-concave}\\
	&g(x), g'(x), f_\mix(x), f(x) > 0~\forall x > 0\label{eq:g-f-positive}\\
	&(f_\mix)'(c) > 0 \label{eq:fmix-increasing}\\
	&\frac{\partial \tilde e_0}{\partial c} > 0 \label{eq:te0-increasing}\\
\end{align}
Equations \eqref{eq:gamma-ineq}, \eqref{eq:cost-convex}, \eqref{eq:g-increasing} and \eqref{eq:g-f-positive} imply
\begin{equation}\label{eq:int-1}
\cost '( g^{-1} ( \frac{g(\tilde e_0)f_\mix(c)}{f(\theta_\true)\cdot \psi_\A} ) ) \le \cost '( g^{-1} ( \frac{g(\tilde e_0)f_\mix(c)}{f(\theta_\true)\cdot \psi_\B} ) )
\end{equation}
Equations \eqref{eq:gamma-ineq}, \eqref{eq:g-concave} and \eqref{eq:g-f-positive} imply
\begin{equation}\label{eq:int-2}
(g^{-1})' ( \frac{g(\tilde e_0)f_\mix(c)}{f(\theta_\true)\cdot \psi_\A} ) \le (g^{-1})' ( \frac{g(\tilde e_0)f_\mix(c)}{f(\theta_\true)\cdot \psi_\B} )
\end{equation}
Equations \eqref{eq:gamma-ineq}, \eqref{eq:g-f-positive},  \eqref{eq:te0-increasing} and \eqref{eq:fmix-increasing} imply
\begin{equation}\label{eq:int-3}
\frac{g(\tilde e_0)(f_\mix)'(c) + f_\mix(c)g'(\tilde e_0) \frac{\partial \tilde e_0}{\partial c}}{f(\theta_\true)\cdot \psi_\A}  < \frac{g(\tilde e_0)(f_\mix)'(c) + f_\mix(c)g'(\tilde e_0) \frac{\partial \tilde e_0}{\partial c}}{f(\theta_\true)\cdot \psi_\B}
\end{equation}
Intermediate equations \eqref{eq:int-1}, \eqref{eq:int-2} and \eqref{eq:int-3} together imply that $\frac{\partial }{\partial c} \swelf^\A(\theta_\true) > \frac{\partial }{\partial c}\swelf^\B(\theta_\true) $. This gives $  \frac{\partial \welfgap(\theta_\true)}{\partial c} > 0$ as desired.

For a two-level policy with cutpoint $c >0$, we have, by definition:
\begin{align*}
	\access &= \frac{\rho}{1-c}\left( 1 - \thresB{c}\right). 
\end{align*}
Since $\thresB{c}  > c$ for any $c\in (0,1-\rho]$, we have that $\access < \rho$. On the other hand, $\access = 0$ for a pure randomization policy.

Taking derivative of $\access$ with respective to $c$,
\begin{align*}
	\frac{\partial\access  }{\partial c} &=  \frac{\rho}{1-c}\left(-\frac{\partial }{\partial c}\thresB{c}\right) + \frac{\rho}{(1-c)^2} \left( 1 -  \thresB{c} \right)\\
	&= \frac{\rho}{1-c}\left(-\frac{\partial }{\partial c}\thresB{c} + \frac{1-\thresB{c} }{1-c} \right). 
\end{align*}
We want to show that the above derivative is non-positive under the assumption that $f^{-1}$ is convex.
Since $\frac{1-\thresB{c} }{1-c} \le 1$ (because $\thresB{c}  \le c$ for any $c\in [0,1-\rho]$), it suffices to show that $\frac{\partial }{\partial c}\thresB{c} \ge 1$. Indeed, we may compute
\begin{align*}
	\frac{\partial }{\partial c}\thresB{c} &= \frac{(f^{-1})'\left(\frac{f_\mix(c)}{\psi_\B}\right) }{\psi_\B} \cdot \left(  \frac{1}{2}\cdot \frac{(f^{-1})'\left(\frac{f_\mix(c)}{\psi_\A}\right) }{\psi_\A} + \frac{1}{2} \cdot \frac{(f^{-1})'\left(\frac{f_\mix(c)}{\psi_\B}\right) }{\psi_\B}   \right)^{-1} \\
	&\ge 1,
\end{align*}
since $\frac{(f^{-1})'\left(\frac{f_\mix(c)}{\psi_\B}\right) }{\psi_\B} \ge \frac{(f^{-1})'\left(\frac{f_\mix(c)}{\psi_\A}\right) }{\psi_\A}$ by the convexity of $f^{-1}$ (which implies $(f^{-1})'$ is non-decreasing) and the fact that $\psi_\A > \psi_\B$.

Consider a single applicant. Denote $i^* := \argmax_{i} \alpha_i\f{i}(\theta_\pre^i)$. Since $\f{i}$'s are strictly monotone and $\theta_\pre^i$ are independently distributed, $i^*$ is almost everywhere unique. For any $e > 0$, let $\e{i^*}^* = e$ and $\e{i}^* = 0$ for each $i \ne i^*$. Then, holding the effort levels of all other applicants fixed, we have
\begin{align*}
	\iwelf(\{ \e{i}^* \}_{i=1}^m, \lambda(\theta_\post^\alpha)) \ge \iwelf(\{ \e{i}\}_{i=1}^m, \lambda(\theta_\post^\alpha)) ~\forall \{ \e{i}\}_{i=1}^m ~s.t. \sum_{i=1}^m e^i = e.
\end{align*}
In other words, for any fixed $\sum_{i=1}^m e^i = e$, the applicant maximizes their welfare by putting all effort into the skill $i^*$ with the highest $\alpha^i\theta_\pre^i$. Therefore, it suffices for the applicant to maximize their individual welfare over the total effort level $e$. At equilibrium, the weighted score $\combscore$ satisfies \[\combscore = h \cdot e \cdot v_\pre^\alpha.\]

Since $\lambda$ is non-decreasing in the weighted score $\combscore$, we may now retrace the proof of Proposition~\ref{lem:rankpreservedindex} to argue the following: if a student with $v_\pre^\alpha$ finds it optimal to achieve weighted score $\combscore$, then each student with $\overline{v_\pre^\alpha}$ finds it optimal to reach weighted score  $\overline{\combscore}\ge\combscore$, due to the convexity of the effort cost function $\cost(e)$.

We prove the result for $g(e_0)  = 0$ to simplify the presentation. The generalization to $g(e_0)$ can be accomplished by some additional book-keeping without modifying the core idea.

Note that in this setting we have $\tilde e_0=\cost^{-1}(\ell_1) =\cost^{-1}\left(\frac{\rho}{1-c}\right) $.

For the measurable skill:
\begin{align*}
	\E[v^M \mid Z=1] &= g(\tilde e_0)\cdot f(c).
\end{align*}


For the unmeasurable skill:
\begin{align*}
	\E[v^U \mid Z=1] &=  \E[g(B-e_1(\potM_\pre))\cdot f(\potM_\pre) \mid Z=1]\\
	&= \E\left[g(B-g^{-1}\left( \frac{g(\tilde e_0)f(c)}{f(\potM_\pre)} \right))\cdot f(\potU_\pre) \mid \potM_\pre > c\right]\\
	&= \E[\potU_\pre]\cdot \int_c^1 g(B-g^{-1}\left( \frac{g(\tilde e_0)f(c)}{f(\potM_\pre)} \right))d\potM_\pre \tag{independence of $\potU_\pre$ and $\potM_\pre$}
\end{align*}

We know that $\frac{\partial}{\partial c}\E[v^M \mid Z=1] > 0$ because $\tilde e_0$ is increasing in $c$.

By the Leibniz integral rule, we have
\begin{align*}
	\frac{\partial}{\partial c}  \E[v^U \mid Z=1] &= \E[\potU_\pre] \cdot \left( - g(B-\tilde e_0) + \int_c^1  \frac{\partial}{\partial c}  g(B-g^{-1}\left( \frac{g(\tilde e_0)f(c)}{f(\potM_\pre)} \right))d\potM_\pre \right)< 0,
\end{align*}
since $g(B-g^{-1}\left( \frac{g(\tilde e_0)f(c)}{f(\potM_\pre)} \right))$ is decreasing in $c$.

For any $c \in (0, 1-\rho)$, set \begin{equation*}
	\alpha = \frac{-\frac{\partial}{\partial c}  \E[v^U \mid Z=1]}{\frac{\partial}{\partial c}\E[v^M \mid Z=1]-\frac{\partial}{\partial c}  \E[v^U \mid Z=1]}.
\end{equation*}
Then we have that \[  \frac{\partial}{\partial c} \Util = \alpha \frac{\partial}{\partial c}\E[v^M \mid Z=1] + (1-\alpha)  \frac{\partial}{\partial c}  \E[v^U \mid Z=1]=0. \] That is, the school's utility $\Util$ for the chosen $\alpha$ is maximized at an interior skill of $c$.

