%        \item $\E[\outcome \mid \A, \theta_\true ] > \E[\outcome \mid \B, \theta_\true ] = 0$ (group $\A$ student has higher probability of admission)
%        \item $\effortA{\theta_\true} > \effortB{\theta_\true} =0$ (group $\A$ student exerts more effort)
