% \propStudentWelfare*
\textbf{Proof of \Cref{prop:student-welfare}.}
\begin{proof}

 We prove this result under more general conditions where $e_0 \ge 0$.

	For a $K$-level policy, we can write the applicant welfare as follows:
	\begin{align*}
	\swelf &= \sum_{i=0}^{K-1}\E\left[ \ell_i - \cost(e_i(\theta_\pre)) \mid \theta_\pre \in \psi_i  \right] \\
	&=\rho - \sum_{i=0}^{K-1}\E\left[ \cost(e_i(\theta_\pre)) \mid \theta_\pre \in \psi_i  \right]  \\
	&\le \rho,
	\end{align*}
	since the term $\E\left[ \cost(e_i(\theta_\pre)) \mid \theta_\pre \in \psi_i  \right]\ge 0$ for any $i$ such that $0 \le i\le K-1$.

	The maximum $\swelf$ is uniquely attained by a two-level $\lambda$ where $c_1 = 0$, $e_i(\theta_\pre) =  e_0$, and so $\cost(e_i(\theta_\pre) ) = 0$ for all $\theta_\pre$.

	In the two-level policy class:
	\begin{align*}
	\swelf &= (1-c)\cdot \E\left[ \ell_1 - \cost( \max(g^{-1} ( \frac{g(\tilde e_0)f(c)}{f(\theta_\pre)} ) , e_0)) \mid \theta_\pre > c \right]\\
	&= \rho - \int_c^1  \cost( \max(g^{-1} ( \frac{g(\tilde e_0)f(c)}{f(\theta_\pre)} ) , e_0)) d\theta_\pre.
	\end{align*}
	Taking the derivative of the above display:
	\begin{align*}
	\frac{\partial \swelf}{\partial c} &= -\cost(\max(\tilde e_0, e_0)) - \int_c^1 \frac{\partial }{\partial c} \cost( \max(g^{-1} ( \frac{g(\tilde e_0)f(c)}{f(\theta_\pre)} ) , e_0)) d\theta_\pre
	%\\
	%&= - \ell_1 - \int_c^1 \frac{\partial }{\partial c} \cost( \max(g^{-1} ( \frac{g(\tilde e_0)f(c)}{f(\theta_\pre)} ) , e_0)) d\theta_\pre
	\end{align*}
	which is non-positive since $\frac{\partial }{\partial c} \cost( \max(g^{-1} ( \frac{g(\tilde e_0)f(c)}{f(\theta_\pre)} ) , e_0)) \ge 0$.
\end{proof}

