% \counterexPrivateUtil*
\begin{samepage}
\noindent\textbf{Proof of \Cref{prop-counterex-priv-util}.}
\begin{proof}[Proof]
Consider the following setting: The effort transfer function $g$ and effort cost function $\cost$ are such that $g(\cost^{-1}(x)) = x$ and $g(e_0) = 0$. We will show the following claim: 

``For any three-level $\lambda$ with levels $(\ell_0, \ell_1, \ell_2) = (0, x, 1)$ and cutpoints $0 < c_1 < c_2 < c_3 = 1$, there exists a skill distribution with quantile function $f$ such that $\Util\pri$ is higher under $\lambda$ than under the two-level policy corresponding to non-randomization."

%By the capacity constraint, we have
%\begin{equation}
%x = \frac{\rho - (1-c_2)}{c_2-c_1}
%\end{equation}

To show that $\Util\pri$ is higher under the three-level policy, we show the following inequality: 
\begin{align}
& g(\tilde e_{0}) \cdot f(c_1)\cdot (c_{2} - c_1) \cdot x+ g(\cost^{-1}(1-x+\cost g^{-1}(\frac{g(\tilde e_0)\cdot f(c_1)}{f(c_2)}))) \cdot f(c_2)\cdot (1 - c_2) \nonumber \\
> ~& g(\cost^{-1}(1)) \cdot f(1-\rho)\cdot \rho, \label{eq:priv_util_3to2}
\end{align}
where $\tilde e_0 = \cost^{-1}(x)$. The LHS is nothing but $\Util\pri$ under a three-level policy, and the RHS, $\Util\pri$ under the two-level policy with cutpoint $1-\rho$.

Using $g(\cost^{-1}(x)) = x$, we can rewrite \eqref{eq:priv_util_3to2} as follows:
\begin{align}\label{eq:simple_priv_util_3to2}
x\cdot f(c_1)\cdot (c_2-c_1)\cdot x + ((1-x)f(c_2)+x\cdot f(c_1)) \cdot (1-c_2) > f(1-\rho) \cdot \rho.
\end{align}

The above display is true whenever $f(c_2)$ is large enough, that is 
\begin{equation*}
f(c_2) >  \frac{f(1-\rho) \cdot \rho - x^2\cdot f(c_1)\cdot (c_2-c_1)-x\cdot f(c_1) \cdot (1-c_2)}{ (1-x)(1-c_2)}.
\end{equation*}
\end{proof}

