\noindent\textbf{Proof of \Cref{prop:linearg}}
	\begin{proof}
		The students are sorted according to their weighted scores:
		\begin{align*}
			\combscore &= \sum_{i=1}^m \alpha_i g(\e{i}) \cdot \f{i}(\theta_\pre^i) \\
			&=h \sum_{i=1}^m  \e{i} \cdot \left(\alpha_i\f{i}(\theta_\pre^i) \right).
		\end{align*}
		Consider a single applicant. Denote $i^* := \argmax_{i} \alpha_i\f{i}(\theta_\pre^i)$. Since $\f{i}$'s are strictly monotone and $\theta_\pre^i$ are independently distributed, $i^*$ is almost everywhere unique. For any $e > 0$, let $\e{i^*}^* = e$ and $\e{i}^* = 0$ for each $i \ne i^*$. Then, holding the effort levels of all other applicants fixed, we have
		\begin{align*}
			\iwelf(\{ \e{i}^* \}_{i=1}^m, \lambda(\theta_\post^\alpha)) \ge \iwelf(\{ \e{i}\}_{i=1}^m, \lambda(\theta_\post^\alpha)) ~\forall \{ \e{i}\}_{i=1}^m ~s.t. \sum_{i=1}^m e^i = e.
		\end{align*}
		In other words, for any fixed $\sum_{i=1}^m e^i = e$, the applicant maximizes their welfare by putting all effort into the skill $i^*$ with the highest $\alpha^i\theta_\pre^i$. Therefore, it suffices for the applicant to maximize their individual welfare over the total effort level $e$. At equilibrium, the weighted score $\combscore$ satisfies \[\combscore = h \cdot e \cdot v_\pre^\alpha.\]

		Since $\lambda$ is non-decreasing in the weighted score $\combscore$, we may now retrace the proof of Proposition~\ref{lem:rankpreservedindex} to argue the following: if a student with $v_\pre^\alpha$ finds it optimal to achieve weighted score $\combscore$, then each student with $\overline{v_\pre^\alpha}$ finds it optimal to reach weighted score  $\overline{\combscore}\ge\combscore$, due to the convexity of the effort cost function $\cost(e)$.
	\end{proof}


% \propWeightedUtil*
\noindent\textbf{Proof of \Cref{prop:2levels-fixedcap}}
\begin{proof}
	We prove the result for $g(e_0)  = 0$ to simplify the presentation. The generalization to $g(e_0)$ can be accomplished by some additional book-keeping without modifying the core idea.

	Note that in this setting we have $\tilde e_0=\cost^{-1}(\ell_1) =\cost^{-1}\left(\frac{\rho}{1-c}\right) $.

	For the measurable skill:
	\begin{align*}
		\E[v^M \mid Z=1] &= g(\tilde e_0)\cdot f(c).
	\end{align*}


	For the unmeasurable skill:
	\begin{align*}
		\E[v^U \mid Z=1] &=  \E[g(B-e_1(\potM_\pre))\cdot f(\potM_\pre) \mid Z=1]\\
		&= \E\left[g(B-g^{-1}\left( \frac{g(\tilde e_0)f(c)}{f(\potM_\pre)} \right))\cdot f(\potU_\pre) \mid \potM_\pre > c\right]\\
		&= \E[\potU_\pre]\cdot \int_c^1 g(B-g^{-1}\left( \frac{g(\tilde e_0)f(c)}{f(\potM_\pre)} \right))d\potM_\pre \tag{independence of $\potU_\pre$ and $\potM_\pre$}
	\end{align*}

	We know that $\frac{\partial}{\partial c}\E[v^M \mid Z=1] > 0$ because $\tilde e_0$ is increasing in $c$.

	By the Leibniz integral rule, we have
	\begin{align*}
		\frac{\partial}{\partial c}  \E[v^U \mid Z=1] &= \E[\potU_\pre] \cdot \left( - g(B-\tilde e_0) + \int_c^1  \frac{\partial}{\partial c}  g(B-g^{-1}\left( \frac{g(\tilde e_0)f(c)}{f(\potM_\pre)} \right))d\potM_\pre \right)< 0,
	\end{align*}
	since $g(B-g^{-1}\left( \frac{g(\tilde e_0)f(c)}{f(\potM_\pre)} \right))$ is decreasing in $c$.

	For any $c \in (0, 1-\rho)$, set \begin{equation*}
		\alpha = \frac{-\frac{\partial}{\partial c}  \E[v^U \mid Z=1]}{\frac{\partial}{\partial c}\E[v^M \mid Z=1]-\frac{\partial}{\partial c}  \E[v^U \mid Z=1]}.
	\end{equation*}
	Then we have that \[  \frac{\partial}{\partial c} \Util = \alpha \frac{\partial}{\partial c}\E[v^M \mid Z=1] + (1-\alpha)  \frac{\partial}{\partial c}  \E[v^U \mid Z=1]=0. \] That is, the school's utility $\Util$ for the chosen $\alpha$ is maximized at an interior skill of $c$.

\end{proof}
